import ast,copy,hashlib,json
from pathlib import Path
root=Path('/workspace')
r=json.load(open('/tmp/runtime-contract.json'))
p=json.loads((root/'proposal.json').read_text())
def validate(value,schema,path='"'$'"'):
 typ=schema.get('type')
 check={'object':lambda x:isinstance(x,dict),'array':lambda x:isinstance(x,list),'string':lambda x:isinstance(x,str),'boolean':lambda x:type(x) is bool}
 if typ in check: assert check[typ](value),(path,typ)
 if 'const' in schema: assert value==schema['const'],path
 if 'enum' in schema: assert value in schema['enum'],path
 if isinstance(value,dict):
  assert set(schema.get('required',[]))<=set(value),(path,'missing required')
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),(path,'unknown keys')
  for k,v in value.items():
   if k in schema.get('properties',{}): validate(v,schema['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),path
  for i,v in enumerate(value): validate(v,schema.get('items',{}),path+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
print('Proposal schema/protocol/evidence/variant identities: PASS')
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
trees=[]
for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 src=(root/v['file']).read_text()
 tree=ast.parse(src)
 compile(src,v['file'],'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,val in config.items():
  default=defaults[k]
  assert (list(default) if isinstance(default,tuple) else default)==val,(v['name'],k)
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','compile','__import__','getattr','setattr'}
  if isinstance(n,ast.Attribute): assert n.attr not in {'load','save','load_state_dict','register_hook','backward','grad','system','popen'}
 normalized=copy.deepcopy(tree)
 for n in normalized.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(value=None)
 for cls in normalized.body:
  if isinstance(cls,ast.ClassDef) and cls.name=='Model':
   fn=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
   for i,a in enumerate(fn.args.args[-len(fn.args.defaults):]):
    if a.arg in {'context_projection_sharing','context_projection_aux_gradient'}: fn.args.defaults[i]=ast.Constant(value=None)
 trees.append(ast.dump(normalized,include_attributes=False))
 print(v['file'],'syntax/config/defaults/imports/source-call audit PASS',hashlib.sha256(src.encode()).hexdigest())
assert len(set(trees))==1
print('Three cells differ only in declared CONFIG/default switches: PASS')
ancestor=(root/'history_g3_r0028_context_route_detached.py').read_text()
assert hashlib.sha256(ancestor.encode()).hexdigest()=='689b96c807bf70d29838437d98a4e4d372fa2d131334dd56edca9f8180816e92'
a=ast.parse(ancestor)
b=ast.parse((root/'candidate.py').read_text())
def methods(tree): return {n.name:ast.dump(n,include_attributes=False) for c in tree.body if isinstance(c,ast.ClassDef) and c.name=='Model' for n in c.body if isinstance(n,ast.FunctionDef)}
am,bm=methods(a),methods(b)
assert set(am)==set(bm)
unchanged=[k for k in am if k not in {'__init__','_context_event_exchange'}]
assert all(am[k]==bm[k] for k in unchanged)
print('Unchanged inherited methods including forward:',len(unchanged),'PASS')
def allocations(tree):
 return [ast.dump(n,include_attributes=False) for n in ast.walk(tree) if isinstance(n,ast.Call) and ((isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn') or (isinstance(n.func,ast.Name) and n.func.id in {'FeatureEmbeddingDict','Dice'}))]
assert allocations(a)==allocations(b)
print('Identical inherited module/parameter allocations and reset calls: PASS')
for file in ['baseline_reference.py','history_baseline_din.py']:
 assert hashlib.sha256((root/file).read_bytes()).hexdigest()==r['context']['protocol']['source_sha256']['baseline.py']
print('Pinned baseline and parent source hashes: PASS')
covered={a['knowledge_id'] for a in p['knowledge_assessments']}
assert {'unirank-method-hyformer','unirank-method-infnet','unirank-method-hemix','unirank-method-mixformer'}<=covered
print('Retrieved industry-card provenance coverage: PASS')
PY"

